const now = new Date();
const formatter = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false
});
const parts = formatter.formatToParts(now);
const getPart = (type) => parts.find(p => p.type === type)?.value || '00';

const dateStr = `${getPart('year')}-${getPart('month')}-${getPart('day')}`;
const timeStr = `${getPart('hour')}h${getPart('minute')}m${getPart('second')}s`;

// Obtenemos el paquete JSON completo (reservas, turnos/settings, mesas, proveedores)
const backupData = $input.item.json.backup_json || $input.item.json;

const jsonString = JSON.stringify(backupData, null, 2);
const fileName = `copia_seguridad_total_${dateStr}_${timeStr}.json`;

return [
  {
    json: {
      fileName: fileName,
      appointmentsCount: (backupData.appointments || []).length,
      hasSettings: !!backupData.settings,
      localTimeMadrid: `${dateStr} ${getPart('hour')}:${getPart('minute')}:${getPart('second')}`
    },
    binary: {
      data: {
        data: Buffer.from(jsonString).toString('base64'),
        mimeType: 'application/json',
        fileName: fileName
      }
    }
  }
];
